function animateNumber(element, values, duration) {
    let index = 0;
    const interval = duration / values.length;
    let startTime = null;

    function updateNumber(timestamp) {
        if (!startTime) startTime = timestamp;

        const elapsed = timestamp - startTime;

        if (elapsed >= interval * index && index < values.length) {
            // Hiển thị số với định dạng 2 chữ số
            element.textContent = values[index].toString().padStart(2, '0');
            index++;
        }

        if (index < values.length) {
            requestAnimationFrame(updateNumber);
        } else {
            // Sau 1 giây thì lặp lại
            setTimeout(() => {
                index = 0;
                startTime = null;
                requestAnimationFrame(updateNumber);
            }, 1000);
        }
    }

    requestAnimationFrame(updateNumber);
}

const numberElement = document.querySelector('.randum__number');
const values = [3, 6, 9, 13, 15, 17, 20, 23, 25];
animateNumber(numberElement, values, 10000);
